// pages/index.js — ARclad Quiz · Híbrido IA + Hardcoded
// Lógica: Q1-Q3 hardcoded → 1 chamada IA gera Q4-Q11 personalizadas → instantâneo
import { useState, useRef } from 'react'
import Head from 'next/head'
import styles from '../styles/Quiz.module.css'

const LOGO = ''
const CONSULTANT = { name: 'Felipe Cenciani', role: 'Consultor Comercial · ARclad do Brasil', email: 'felipe.cenciani@arclad.com' }
const BASE_QS   = [{"id": 1, "bloco": "Sobre você e seu negócio", "q": "Qual é o seu segmento?", "opts": ["Gráfica ou convertedor", "Marca ou indústria", "Agência ou marketing", "Distribuidor de insumos"], "r": null}, {"id": 2, "bloco": "Sobre você e seu negócio", "q": "Faturamento anual da empresa?", "opts": ["Até R$ 500 mil", "R$ 500 mil a R$ 2 milhões", "R$ 2 a R$ 10 milhões", "Acima de R$ 10 milhões"], "r": null}, {"id": 3, "bloco": "Sobre você e seu negócio", "q": "Qual o volume médio mensal de material?", "opts": ["Até 5.000 m²", "5.000 a 20.000 m²", "20.000 a 100.000 m²", "Acima de 100.000 m²"], "r": null}]
const FALLBACK_QS = [{"id": 4, "bloco": "Sobre você e seu negócio", "q": "Como você chegou até a ARclad?", "opts": ["Já sou cliente", "Conhecia mas nunca comprei", "Já ouvi falar", "Conheci aqui na feira hoje"], "r": null}, {"id": 5, "bloco": "Sobre você e seu negócio", "q": "O que te trouxe ao nosso stand?", "opts": ["Queria ver os materiais", "Indicação de alguém", "Entender o portfólio", "Inovação e suporte técnico"], "r": null}, {"id": 6, "bloco": "Sobre você e seu negócio", "q": "Qual material você mais compra hoje?", "opts": ["BOPP (brilho, fosco, metalizado)", "Couché (brilho ou fosco)", "Térmico (direto ou transfer)", "Linhas especiais (PET, sustentáveis)"], "r": null}, {"id": "6b", "bloco": "Sobre você e seu negócio", "q": "Qual linha especial te interessa?", "opts": ["PET / Poliéster", "BOPP especial / metalizado", "Térmico especial", "Sustentável"], "r": null, "condicional6b": true}, {"id": 7, "bloco": "Sobre você e seu negócio", "q": "Como avalia o suporte técnico do seu fornecedor atual?", "opts": ["Excelente", "Razoável", "Ruim", "Não tenho suporte"], "r": null}, {"id": "7b", "bloco": "Sobre você e seu negócio", "q": "Por que o suporte não é excelente?", "opts": ["Demora para responder", "Não conhece bem os materiais", "Não resolve meus problemas técnicos", "Não oferece suporte proativo"], "r": null, "condicional": true}, {"id": 8, "bloco": "Pergunta técnica", "q": "Qual a função do liner siliconado no material autoadesivo?", "opts": ["É o adesivo que gruda no produto", "É o suporte que protege o adesivo até a aplicação", "É a camada que recebe a impressão", "É o verniz de acabamento"], "r": 1, "feedback": "O liner siliconado é apenas o suporte que protege o adesivo. O adesivo fica entre o liner e o facestock."}, {"id": 9, "bloco": "Sobre você e seu negócio", "q": "Qual é o seu maior desafio com materiais hoje?", "opts": ["Preço alto", "Prazo imprevisível / falta de estoque", "Falta de variedade no portfólio", "Suporte técnico fraco"], "r": null}, {"id": 10, "bloco": "Sobre você e seu negócio", "q": "O que te faria trocar de fornecedor?", "opts": ["Preço melhor", "Material de maior qualidade", "Suporte técnico especializado", "Entrega rápida e estoque garantido"], "r": null}, {"id": 11, "bloco": "Sobre você e seu negócio", "q": "Tem projeto de material nos próximos 3 meses?", "opts": ["Sim, projeto concreto", "Sim, em fase de orçamento", "Talvez", "Não por enquanto"], "r": null}]

export default function App() {
  const [fairName, setFairName]       = useState('Flexo & Labels')
  const [ready, setReady]             = useState(false)
  const [screen, setScreen]           = useState('welcome')
  const [flow, setFlow]               = useState([])
  const [qIdx, setQIdx]               = useState(0)
  const [answers, setAnswers]         = useState({})
  const [answerLabels, setAnswerLabels] = useState({})
  const [selIdx, setSelIdx]           = useState(null)
  const [showFeedback, setShowFeedback] = useState(false)
  const [feedbackText, setFeedbackText] = useState('')
  const [personalizing, setPersonalizing] = useState(false)
  const [loading, setLoading]         = useState(false)
  const [finalText, setFinalText]     = useState('')
  const [fp, setFp]                   = useState(null)
  const [cNome, setCNome]             = useState('')
  const [cEmp, setCEmp]               = useState('')
  const [cCargo, setCCargo]           = useState('')
  const [cFone, setCFone]             = useState('')
  const [cEmail, setCEmail]           = useState('')
  const [cErr, setCErr]               = useState({})
  const [saved, setSaved]             = useState(false)
  const [npsRated, setNpsRated]       = useState(null)
  const [logoClicks, setLogoClicks]   = useState(0)
  const [showPin, setShowPin]         = useState(false)
  const [pinVal, setPinVal]           = useState('')
  const [leads, setLeads]             = useState([])
  const [adminFilter, setAdminFilter] = useState('todos')
  const [adminTab, setAdminTab]       = useState('leads')
  const logoTimer = useRef(null)

  const curQ    = flow[qIdx] || null
  const totalQ  = flow.length
  const pct     = totalQ > 0 ? Math.min(5 + (qIdx / totalQ) * 88, 95) : 5
  const techQs  = flow.filter(q => q.r !== null && q.r !== undefined)
  const techTotal = Object.keys(answers).filter(k => flow.find(q => String(q.id)===k && q.r!==null && q.r!==undefined)).length
  const score   = Object.entries(answers).filter(([k,v]) => {
    const q = flow.find(q => String(q.id)===k)
    return q && q.r!==null && q.r!==undefined && v===q.r
  }).length

  const startQuiz = () => {
    setFlow(BASE_QS)
    setQIdx(0); setAnswers({}); setAnswerLabels({})
    setSelIdx(null); setShowFeedback(false); setFeedbackText('')
    setFinalText(''); setFp(null); setPersonalizing(false)
    setScreen('quiz')
  }

  // Após Q1-Q3, personalizar o quiz com IA
  const personalizeQuiz = async (baseAnswers, baseLabels) => {
    setPersonalizing(true)
    const seg   = baseLabels['1'] || ''
    const fat   = baseLabels['2'] || ''
    const skus  = baseLabels['3'] || ''

    try {
      const res = await fetch('/api/quiz-personalize', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ segmento: seg, faturamento: fat, skus, feira: fairName }),
      })
      const data = await res.json()
      if (!res.ok || !data.questions) throw new Error('sem perguntas')
      // Validar e filtrar perguntas malformadas
      const validated = data.questions.filter(q => {
        return q && typeof q === 'object' && q.id && typeof q.q === 'string' && Array.isArray(q.opts) && q.opts.length === 4
      })
      if (validated.length < 8) throw new Error('perguntas insuficientes')
      // Filtrar perguntas condicionais
      const personalizedFlow = validated.filter(q => {
        if (q.condicional) {
          const p7ans = baseAnswers['7']
          return p7ans !== undefined && p7ans !== 0
        }
        return true
      })
      setFlow([...BASE_QS, ...personalizedFlow])
    } catch(e) {
      // Fallback: usar perguntas padrão
      const fallback = FALLBACK_QS.filter(q => {
        if (q.condicional) return false
        return true
      })
      setFlow([...BASE_QS, ...fallback])
    }
    setQIdx(BASE_QS.length) // avança para primeira personalizada
    setSelIdx(null); setShowFeedback(false)
    setPersonalizing(false)
  }

  const pickAns = (idx) => {
    if (selIdx !== null || personalizing) return
    if (!curQ || !Array.isArray(curQ.opts) || !curQ.opts[idx]) return
    setSelIdx(idx)
    const q = curQ
    const newAnswers = { ...answers, [String(q.id)]: idx }
    const newLabels  = { ...answerLabels, [String(q.id)]: q.opts[idx] }
    setAnswers(newAnswers)
    setAnswerLabels(newLabels)

    const isTech = q.r !== null && q.r !== undefined
    const errou  = isTech && idx !== q.r

    if (errou) {
      setFeedbackText(q.feedback || 'Reveja: ' + q.opts[q.r])
      setShowFeedback(true)
    } else {
      setTimeout(() => advance(newAnswers, newLabels, idx), errou ? 0 : 700)
    }
  }

  const advance = (ans, labels, idx) => {
    const isLastBase = qIdx === BASE_QS.length - 1
    if (isLastBase) {
      // Fim das 3 base → personalizar com IA
      personalizeQuiz(ans, labels)
    } else if (qIdx + 1 >= flow.length) {
      // Fim do quiz → análise final
      setScreen('capture_wait')
      fetchAnalysis(ans, labels, flow)
    } else {
      // Próxima pergunta — verificar condicional P7b
      let next = qIdx + 1
      while (next < flow.length) {
        const nq = flow[next]
        if (nq.condicional) {
          const p7 = ans['7']
          if (p7 === undefined || p7 === 0) { next++; continue }
        }
        break
      }
      if (next >= flow.length) {
        setScreen('capture_wait')
        fetchAnalysis(ans, labels, flow)
      } else {
        setQIdx(next)
        setSelIdx(null); setShowFeedback(false); setFeedbackText('')
      }
    }
  }

  const fetchAnalysis = async (ans, labels, flowUsed) => {
    setLoading(true)
    const summary = flowUsed
      .filter(q => ans[String(q.id)] !== undefined)
      .map(q => `${q.q}: ${labels[String(q.id)] || q.opts[ans[String(q.id)]]}`)
      .join(' | ')
    let lastErr = null
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const res = await fetch('/api/chat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ messages: [{ role: 'user', content: `Visitante na feira ${fairName}: ${summary}` }] }),
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.error || '')
        let parsed = null
        try { const m = data.text?.match(/\{[\s\S]*\}/); if (m) parsed = JSON.parse(m[0]) } catch(e) {}
        setFp(parsed || { temperatura: 'morno', oportunidade: 'Portfólio completo ARclad para sua operação.', nivel: 'Tecnico', prioridade: 'Media' })
        setLoading(false); setScreen('capture'); return
      } catch(e) { lastErr = e; if (attempt===0) await new Promise(r=>setTimeout(r,1200)) }
    }
    setLoading(false)
    const t = ans['11']!==undefined&&ans['11']<=1?'quente':ans['11']===2?'morno':'frio'
    setFp({ temperatura: t, oportunidade: 'Suporte técnico especializado ARclad para sua operação.', nivel: 'Tecnico', prioridade: t==='quente'?'Alta':'Media' })
    setScreen('capture')
  }

  const saveLead = async () => {
    const e = {}
    if (!cNome.trim()) e.nome = true
    if (!cEmp.trim())  e.emp  = true
    if (!cFone.trim()) e.fone = true
    setCErr(e)
    if (Object.keys(e).length) return
    const lead = {
      nome: cNome.trim(), empresa: cEmp.trim(), cargo: cCargo.trim()||null,
      whatsapp: cFone.trim(), email: cEmail.trim()||null,
      pais: 'BR', feira: fairName||null,
      segmento:        answerLabels['1']||null,
      faturamento:     answerLabels['2']||null,
      skus:            answerLabels['3']||null,
      conhecia_arclad: answers['4']!==undefined?['ja_cliente','conhecia','ouviu_falar','nao_conhecia'][answers['4']]:null,
      atracao_stand:   answerLabels['5']||null,
      materiais:       answerLabels['6']||null,
      suporte_fornecedor: answerLabels['7']||null,
      motivo_suporte:  answerLabels['7b']||null,
      desafio:         answerLabels['9']||answerLabels['desafio']||null,
      gatilho_compra:  answerLabels['10']||answerLabels['gatilho']||null,
      timing:          answerLabels['11']||answerLabels['timing']||null,
      nivel_tecnico:   fp?.nivel||null,
      temperatura:     fp?.temperatura||'morno',
      oportunidade:    fp?.oportunidade||null,
      prioridade_followup: fp?.prioridade||'Media',
      locale: 'pt',
    }
    try {
      const r = await fetch('/api/leads', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(lead) })
      if (r.ok) setSaved(true)
      else console.error('Falha ao salvar:', await r.text())
    } catch(e) { console.error('Erro saveLead:', e) }
    setScreen('result')
  }

  const saveNps = async (rating) => {
    setNpsRated(rating)
    try { await fetch('/api/leads', { method:'PATCH', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ nps: rating, whatsapp: cFone.trim() }) }) } catch(e) {}
  }

  const generateLetter = () => {
    const date = new Date().toLocaleDateString('pt-BR')
    const w = window.open('', '_blank')
    if (!w) { alert('Permita popups para gerar a carta.'); return }
    w.document.write(`<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><title>Recomendação ARclad — ${cNome}</title>
<style>@page{size:A4;margin:25mm}*{box-sizing:border-box;margin:0;padding:0;font-family:Inter,-apple-system,sans-serif}body{color:#003232;line-height:1.6}.header{border-bottom:4px solid #C9FF1F;padding-bottom:16px;margin-bottom:30px;display:flex;justify-content:space-between;align-items:center}.brand{font-size:28px;font-weight:900;color:#003232}.tag{font-size:10px;color:#5A9A7A;letter-spacing:.18em;text-transform:uppercase;font-weight:700;margin-top:2px}.date{font-size:12px;color:#5A9A7A}h1{font-size:22px;font-weight:900;margin-bottom:6px}.subtitle{font-size:13px;color:#5A9A7A;font-weight:600;margin-bottom:28px;letter-spacing:.05em;text-transform:uppercase}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:24px}.box{background:#F5FAEF;border-left:4px solid #00B22B;padding:14px 18px;border-radius:0 6px 6px 0}.label{font-size:10px;color:#5A9A7A;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin-bottom:4px}.value{font-size:14px;color:#003232;font-weight:600}p{font-size:14px;margin-bottom:12px;color:#333}.reco{background:#003232;color:white;padding:24px;border-radius:12px;margin:24px 0}.reco h2{font-size:10px;font-weight:800;color:#C9FF1F;letter-spacing:.18em;text-transform:uppercase;margin-bottom:10px}.reco p{color:white;font-size:15px;line-height:1.65;margin:0}.footer{border-top:1px solid #E9E9E9;padding-top:20px;margin-top:30px}.sig{display:flex;align-items:center;gap:14px}.av{width:52px;height:52px;border-radius:50%;background:#003232;color:#C9FF1F;display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:900;flex-shrink:0}.name{font-size:16px;font-weight:800;color:#003232}.role{font-size:11px;color:#5A9A7A}.email{font-size:13px;color:#00B22B;font-weight:600;margin-top:2px}.btn-print{background:#C9FF1F;color:#003232;border:none;padding:14px 30px;font-size:15px;font-weight:800;border-radius:10px;cursor:pointer;box-shadow:0 4px 14px rgba(201,255,31,.4)}.print-bar{position:fixed;top:20px;right:20px;z-index:100}@media print{.no-print{display:none}}</style></head>
<body>
<div class="print-bar no-print"><button class="btn-print" onclick="window.print()">🖨️ Imprimir / Salvar PDF</button></div>
<div style="position:relative">
<div style="position:absolute;top:0;right:0;font-size:9px;color:#C9FF1F;background:#003232;padding:4px 10px;border-radius:0 0 0 8px;font-weight:700;letter-spacing:.1em">DIAGNÓSTICO TÉCNICO</div>
<div class="header"><div><div class="brand">ARclad</div><div class="tag">Materiais Autoadesivos · Silicone · Laminação</div></div><div class="date">${date}</div></div>
<h1>Recomendação Técnica Personalizada</h1>
<div class="subtitle">Para: ${cNome.toUpperCase()} · ${cEmp.toUpperCase()}</div>
<div class="grid">
<div class="box"><div class="label">Segmento</div><div class="value">${answerLabels['1']||'-'}</div></div>
<div class="box"><div class="label">Faturamento</div><div class="value">${answerLabels['2']||'-'}</div></div>
<div class="box"><div class="label">Material Principal</div><div class="value">${answerLabels['6']||answerLabels['materiais']||'-'}</div></div>
<div class="box"><div class="label">Timing</div><div class="value">${answerLabels['11']||answerLabels['timing']||'-'}</div></div>
</div>
<p>Prezado(a) <strong>${cNome}</strong>,</p>
<p>Com base na sua participação no <strong>Consultor Interativo ARclad</strong> durante a feira <strong>${fairName}</strong>, identificamos o perfil técnico da sua operação e preparamos esta recomendação:</p>
<div class="reco"><h2>OPORTUNIDADE IDENTIFICADA</h2><p>${fp?.oportunidade||'Portfólio completo ARclad com suporte técnico especializado.'}</p></div>
<p>A <strong>ARclad</strong> é distribuidora especializada com unidades em Rionegro e Cartagena (Colômbia), oferecendo portfólio completo de BOPP, Couché, substratos térmicos e materiais autoadesivos com suporte técnico especializado pré e pós-venda.</p>
<div class="footer"><div class="sig"><div class="av">FC</div><div><div class="name">Felipe Cenciani</div><div class="role">Consultor Comercial · ARclad do Brasil</div><div class="email">felipe.cenciani@arclad.com</div></div></div></div>
</div></body></html>`)
    w.document.close()
  }

  const openAdmin = async () => {
    try { const r = await fetch('/api/leads?pais=BR'); const d = await r.json(); setLeads(d.leads||[]) } catch(e) { setLeads([]) }
    setScreen('admin')
  }

  const handleLogoClick = () => {
    const n = logoClicks+1; setLogoClicks(n); clearTimeout(logoTimer.current)
    if (n>=5) { setLogoClicks(0); setShowPin(true); setPinVal('') }
    else logoTimer.current = setTimeout(()=>setLogoClicks(0), 2000)
  }
  const handlePin = v => {
    setPinVal(v)
    if (v.length===4) { if (v==='7777') { setShowPin(false); openAdmin() } else setPinVal('') }
  }

  const exportExcel = () => {
    if (!leads.length) { alert('Nenhum lead para exportar.'); return }
    const XLSX = window.XLSX
    if (!XLSX) { alert('Biblioteca Excel não carregada. Recarregue a página.'); return }

    const tM = {quente:'🔥 Quente', morno:'⛅ Morno', frio:'❄️ Frio'}
    const pM = {Alta:'🔴 Alta', Media:'🟡 Média', Baixa:'🟢 Baixa'}
    const aM = {ja_cliente:'✅ Já cliente', conhecia:'👀 Conhecia', ouviu_falar:'👂 Ouviu falar', nao_conhecia:'🆕 Conheceu na feira'}
    const nM = {otimo:'😊 Ótimo', neutro:'😐 Neutro', ruim:'😞 Ruim'}

    const order = {quente:0, morno:1, frio:2}
    const sorted = [...leads].sort((a,b) => (order[a.temperatura]||2) - (order[b.temperatura]||2))

    const wb = XLSX.utils.book_new()

    // ── ABA 1: Followup ──────────────────────────────────
    const followupHeaders = ['PRIORIDADE','TEMPERATURA','NOME','EMPRESA','CARGO','WHATSAPP','E-MAIL','SEGMENTO','MATERIAL','DESAFIO','TIMING','OPORTUNIDADE ARclad','NÍVEL','CONHECIA ARclad','NPS','DATA']
    const followupRows = sorted.map(l => [
      pM[l.prioridade_followup]||l.prioridade_followup||'-',
      tM[l.temperatura]||'-',
      l.nome||'-', l.empresa||'-', l.cargo||'-', l.whatsapp||'-', l.email||'-',
      l.segmento||'-', l.materiais||'-', l.desafio||'-', l.timing||'-',
      l.oportunidade||'-', l.nivel_tecnico||'-',
      aM[l.conhecia_arclad]||l.conhecia_arclad||'-',
      nM[l.nps]||l.nps||'-',
      l.created_at ? new Date(l.created_at).toLocaleDateString('pt-BR') : '-',
    ])
    const ws1 = XLSX.utils.aoa_to_sheet([followupHeaders, ...followupRows])
    ws1['!cols'] = [10,12,22,22,16,16,24,20,22,24,20,38,12,18,10,12].map(w=>({wch:w}))
    XLSX.utils.book_append_sheet(wb, ws1, 'Followup')

    // ── ABA 2: Dados Completos ────────────────────────────
    const dadosHeaders = ['NOME','EMPRESA','CARGO','WHATSAPP','E-MAIL','PAÍS','FEIRA','SEGMENTO','FATURAMENTO','SKUs','MATERIAL','SUPORTE ATUAL','MOTIVO SUPORTE','DESAFIO','GATILHO TROCA','TIMING','TEMPERATURA','PRIORIDADE','NÍVEL','OPORTUNIDADE ARclad','CONHECIA ARclad','ATRAÇÃO STAND','NPS','DATA']
    const dadosRows = leads.map(l => [
      l.nome||'-', l.empresa||'-', l.cargo||'-', l.whatsapp||'-', l.email||'-',
      l.pais||'BR', l.feira||'-', l.segmento||'-', l.faturamento||'-', l.skus||'-',
      l.materiais||'-', l.suporte_fornecedor||'-', l.motivo_suporte||'-',
      l.desafio||'-', l.gatilho_compra||'-', l.timing||'-',
      tM[l.temperatura]||'-', pM[l.prioridade_followup]||'-', l.nivel_tecnico||'-',
      l.oportunidade||'-', aM[l.conhecia_arclad]||l.conhecia_arclad||'-',
      l.atracao_stand||'-', nM[l.nps]||l.nps||'-',
      l.created_at ? new Date(l.created_at).toLocaleString('pt-BR') : '-',
    ])
    const ws2 = XLSX.utils.aoa_to_sheet([dadosHeaders, ...dadosRows])
    ws2['!cols'] = [22,22,16,16,24,8,20,20,22,14,22,16,24,24,24,24,14,12,12,38,18,20,10,18].map(w=>({wch:w}))
    XLSX.utils.book_append_sheet(wb, ws2, 'Dados Completos')

    // ── ABA 3: Resumo ─────────────────────────────────────
    const quentes = leads.filter(l=>l.temperatura==='quente')
    const mornos  = leads.filter(l=>l.temperatura==='morno')
    const frios   = leads.filter(l=>l.temperatura==='frio')
    const segs    = {}; leads.forEach(l=>{if(l.segmento)segs[l.segmento]=(segs[l.segmento]||0)+1})
    const awCnt   = {}; leads.forEach(l=>{if(l.conhecia_arclad){const k=aM[l.conhecia_arclad]||l.conhecia_arclad; awCnt[k]=(awCnt[k]||0)+1}})
    const npsCnt  = {}; leads.forEach(l=>{if(l.nps){const k=nM[l.nps]||l.nps; npsCnt[k]=(npsCnt[k]||0)+1}})

    const resumo = [
      [`ARclad — Resumo Executivo · ${fairName}`],
      [],
      ['MÉTRICAS GERAIS',''],
      ['Total de leads', leads.length],
      ['Quentes', quentes.length],
      ['Mornos', mornos.length],
      ['Frios', frios.length],
      ['Com WhatsApp', leads.filter(l=>l.whatsapp).length],
      ['Prioridade Alta', leads.filter(l=>l.prioridade_followup==='Alta').length],
      [],
      ['POR SEGMENTO',''],
      ...Object.entries(segs).sort((a,b)=>b[1]-a[1]).map(([k,v])=>[k,v]),
      [],
      ['BRAND AWARENESS ARclad',''],
      ...Object.entries(awCnt).sort((a,b)=>b[1]-a[1]).map(([k,v])=>[k,v]),
      [],
      ['NPS (FEEDBACK)',''],
      ...Object.entries(npsCnt).map(([k,v])=>[k,v]),
      [],
      ['FOLLOWUP URGENTE (QUENTES)','',''],
      ['Nome','WhatsApp','Oportunidade'],
      ...quentes.map(l=>[l.nome, l.whatsapp, l.oportunidade]),
    ]
    const ws3 = XLSX.utils.aoa_to_sheet(resumo)
    ws3['!cols'] = [{wch:32},{wch:14},{wch:45}]
    XLSX.utils.book_append_sheet(wb, ws3, 'Resumo')

    const fname = `ARclad_Leads_${(fairName||'Feira').replace(/\s+/g,'_')}_${new Date().toISOString().slice(0,10)}.xlsx`
    XLSX.writeFile(wb, fname)
  }

  const fl = leads.filter(l=>adminFilter==='todos'||l.temperatura===adminFilter)

  // ══ SETUP ══
  if (!ready) return (
    <div className={styles.bg}>
      <Head><title>ARclad · Quiz Interativo</title><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"/></Head>
      <div className={styles.wrap}><div className={styles.card}>
        <div className={styles.topAccent}/><div className={styles.geoTL}/><div className={styles.geoBR}/>
        <div className={styles.logoArea}>
          <img src={`data:image/png;base64,${LOGO}`} className={styles.logoImgLg} alt="ARclad"/>
          <div className={styles.logoSub}>Consultor Interativo com IA</div>
        </div>
        <h1 className={styles.title} style={{marginBottom:6}}>Bem-vindo à</h1>
        <h1 className={styles.title} style={{color:'var(--brand-lime)',marginBottom:20}}>{fairName}</h1>
        <div className={styles.setupGroup}>
          <label className={styles.inpLabel}>Nome da Feira</label>
          <input className={styles.inp} type="text" value={fairName} onChange={e=>setFairName(e.target.value)} placeholder="Ex: Fispal 2025"/>
        </div>
        <button className={styles.btnPrimary} onClick={()=>setReady(true)}>Entrar no quiz →</button>
      </div></div>
    </div>
  )

  // ══ WELCOME ══
  if (screen==='welcome') return (
    <div className={styles.bg}>
      <Head><title>ARclad · Consultor Interativo</title></Head>
      <div className={styles.wrap}><div className={styles.card}>
        <div className={styles.topAccent}/><div className={styles.geoTL}/><div className={styles.geoBR}/>
        <div className={styles.logoArea}>
          <img src={`data:image/png;base64,${LOGO}`} className={styles.logoImgLg} alt="ARclad" onClick={handleLogoClick} style={{cursor:'default'}}/>
          <div className={styles.logoSub}>Materiais Autoadesivos · Silicone · Laminação</div>
        </div>
        <h1 className={styles.title}>Descubra o que a ARclad pode fazer por você</h1>
        <p className={styles.desc}>Nosso consultor virtual vai conhecer seu negócio e seus desafios. Resultado 100% personalizado em menos de 2 minutos.</p>
        <div className={styles.pills}>
          {['IA ao vivo','Personalizado','~2 minutos','Grátis'].map(p=><span key={p} className={styles.pill}>{p}</span>)}
        </div>
        <button className={styles.btnPrimary} onClick={startQuiz}>▶ Começar agora</button>
      </div></div>
      {showPin&&<Pin val={pinVal} onVal={handlePin} onCancel={()=>setShowPin(false)}/>}
    </div>
  )

  // ══ QUIZ ══
  if (screen==='quiz') {
    if (personalizing) return (
      <div className={styles.bg}>
        <Head><title>ARclad · Personalizando...</title></Head>
        <div className={styles.wrap}><div className={styles.card}>
          <div className={styles.topAccent}/>
          <div style={{textAlign:'center',padding:'30px 0'}}>
            <div className={styles.ldg} style={{justifyContent:'center',marginBottom:14}}>
              <div className={styles.spin}/>
              <span style={{fontSize:'.95rem',fontWeight:700,color:'var(--brand-lime)'}}>Personalizando seu quiz...</span>
            </div>
            <p className={styles.desc}>Nossa IA está adaptando as perguntas ao seu perfil. Só um segundo!</p>
          </div>
        </div></div>
      </div>
    )
    if (!curQ) return null
    const isTech = curQ.r !== null && curQ.r !== undefined
    return (
      <div className={styles.bg}>
        <Head><title>ARclad · Quiz</title></Head>
        <div className={styles.wrap}><div className={styles.card}>
          <div className={styles.topAccent}/>
          <div className={styles.topbar}>
            <span className={styles.qlbl}>{qIdx<BASE_QS.length ? `Pergunta ${qIdx+1} de ${totalQ}` : `Pergunta ${qIdx+1} de ${totalQ}`}</span>
            <span className={styles.qpts}>{techTotal>0?`${score}/${techTotal} técnicas`:''}</span>
          </div>
          <div className={styles.pbar}><div className={styles.pfill} style={{width:`${pct}%`}}/></div>
          {showFeedback&&<div className={styles.feedback}><strong>Atenção:</strong> {feedbackText}</div>}
          <div className={styles.qbox}>
            <div className={`${styles.qnum} ${isTech?styles.qnumTech:styles.qnumProfile}`}>
              {isTech?'Pergunta técnica':'Sobre você e seu negócio'}
            </div>
            <div className={styles.qtxt}>{curQ.q}</div>
          </div>
          <div className={styles.opts}>
            {Array.isArray(curQ.opts) && curQ.opts.map((opt,i)=>{
              const isRight = isTech&&i===curQ.r&&selIdx!==null
              const isWrong = isTech&&selIdx===i&&i!==curQ.r
              const isNeu   = !isTech&&selIdx===i
              return (
                <button key={i} disabled={selIdx!==null||personalizing} onClick={()=>pickAns(i)}
                  className={`${styles.opt} ${isRight?styles.optOk:isWrong?styles.optNo:isNeu?styles.optNeu:''}`}>
                  <span className={styles.ol}>{['A','B','C','D'][i]}</span>
                  <span>{opt}</span>
                </button>
              )
            })}
          </div>
          {showFeedback&&selIdx!==null&&(
            <button className={styles.btnPrimary} onClick={()=>advance(answers,answerLabels,selIdx)}>Próxima →</button>
          )}
        </div></div>
      </div>
    )
  }

  // ══ AGUARDANDO ANÁLISE ══
  if (screen==='capture_wait') return (
    <div className={styles.bg}>
      <Head><title>ARclad · Analisando...</title></Head>
      <div className={styles.wrap}><div className={styles.card}>
        <div className={styles.topAccent}/>
        <div className={styles.logoArea}><img src={`data:image/png;base64,${LOGO}`} className={styles.logoImgSm} alt="ARclad"/></div>
        <div style={{textAlign:'center',padding:'20px 0'}}>
          <div className={styles.ldg} style={{justifyContent:'center',marginBottom:14}}>
            <div className={styles.spin}/>
            <span style={{fontSize:'1rem',fontWeight:600,color:'var(--brand-lime)'}}>Gerando sua análise personalizada...</span>
          </div>
          <p className={styles.desc}>Nossa IA está processando suas respostas. Aguarde alguns segundos.</p>
        </div>
      </div></div>
    </div>
  )

  // ══ CAPTURE ══
  if (screen==='capture') return (
    <div className={styles.bg}>
      <Head><title>ARclad · Seus dados</title></Head>
      <div className={styles.wrap}><div className={styles.card}>
        <div className={styles.topAccent}/><div className={styles.geoTL}/><div className={styles.geoBR}/>
        <div className={styles.logoArea} style={{marginBottom:18}}>
          <img src={`data:image/png;base64,${LOGO}`} className={styles.logoImgSm} alt="ARclad"/>
        </div>
        <h1 className={styles.title} style={{fontSize:'1.2rem',marginBottom:6}}>Quase lá! 🎯</h1>
        <p className={styles.desc} style={{marginBottom:20}}>Deixe seus dados para receber suas recomendações e nosso consultor entrar em contato.</p>
        {[
          {id:'nome',label:'Nome completo *',ph:'Seu nome',val:cNome,set:setCNome,type:'text'},
          {id:'emp', label:'Empresa *',       ph:'Nome da empresa',val:cEmp,set:setCEmp,type:'text'},
          {id:'cargo',label:'Cargo / Função', ph:'Ex: Gerente, Sócio, Diretor...',val:cCargo,set:setCCargo,type:'text'},
          {id:'fone',label:'WhatsApp *',       ph:'(11) 99999-9999',val:cFone,set:setCFone,type:'tel'},
          {id:'email',label:'E-mail',          ph:'email@empresa.com',val:cEmail,set:setCEmail,type:'email'},
        ].map(f=>(
          <div key={f.id}>
            <label className={styles.inpLabel}>{f.label}</label>
            <input className={`${styles.inp} ${cErr[f.id]?styles.inpErr:''}`}
              type={f.type} placeholder={f.ph} value={f.val} onChange={e=>f.set(e.target.value)}/>
          </div>
        ))}
        <button className={styles.btnPrimary} style={{marginTop:6}} onClick={saveLead}>Ver meu resultado →</button>
      </div></div>
    </div>
  )

  // ══ RESULT ══
  if (screen==='result') {
    const p = techTotal>0?score/techTotal:0
    const m = p===1?{e:'🏆',t:'Expert técnico!',n:'ESPECIALISTA EM MATERIAIS'}
      :p>=.75?{e:'🎯',t:'Excelente!',n:'ESPECIALISTA'}
      :p>=.5?{e:'💪',t:'Bom conhecimento!',n:'TÉCNICO'}
      :{e:'👋',t:'Obrigado pela conversa!',n:'VISITANTE'}
    return (
      <div className={styles.bg}>
        <Head><title>ARclad · Resultado</title></Head>
        <div className={styles.wrap}><div className={styles.card}>
          <div className={styles.topAccent}/><div className={styles.geoTL}/><div className={styles.geoBR}/>
          <div style={{textAlign:'center',marginBottom:6}}>
            <div style={{fontSize:'3.2rem',marginBottom:7}}>{m.e}</div>
            <div className={styles.rtitle}>{m.t}</div>
            <div className={styles.rnivel}>{m.n}</div>
          </div>
          {saved&&<div className={styles.savedMsg}>✓ Dados salvos! Entraremos em contato em breve.</div>}
          {fp?.oportunidade&&(
            <div style={{background:'rgba(201,255,31,.07)',border:'1.5px solid rgba(201,255,31,.22)',borderRadius:14,padding:'14px 18px',marginBottom:16,fontSize:'.9rem',lineHeight:1.65}}>
              <div style={{fontSize:'.65rem',fontWeight:700,color:'var(--brand-lime)',letterSpacing:'.12em',textTransform:'uppercase',marginBottom:6}}>Oportunidade ARclad para você</div>
              <strong style={{color:'var(--brand-white)'}}>{fp.oportunidade}</strong>
            </div>
          )}
          <div className={styles.sep}/>
          <div className={styles.cta}>
            <div className={styles.ctaTitle}>👋 Fale com nosso consultor</div>
            <div className={styles.ctaRow}>
              <div className={styles.ctaAv}>👤</div>
              <div>
                <div className={styles.ctaName}>{CONSULTANT.name}</div>
                <div className={styles.ctaRole}>{CONSULTANT.role}</div>
                <div className={styles.ctaEmail}>{CONSULTANT.email}</div>
              </div>
            </div>
            <div className={styles.ctaMsg}>Estou aqui no stand! Vamos encontrar o material certo para o seu negócio.</div>
          </div>
          <button className={styles.btnOut} onClick={generateLetter} style={{marginTop:0,marginBottom:12}}>📄 Gerar carta de recomendação técnica</button>
          {npsRated===null?(
            <div style={{background:'rgba(201,255,31,.05)',border:'1px solid rgba(201,255,31,.16)',borderRadius:12,padding:'14px 16px',marginBottom:12,textAlign:'center'}}>
              <div style={{fontSize:'.78rem',fontWeight:600,color:'var(--brand-lime)',marginBottom:8}}>Como foi sua experiência?</div>
              <div style={{display:'flex',justifyContent:'center',gap:14}}>
                {['😞','😐','😊'].map((e,i)=>(
                  <button key={i} onClick={()=>saveNps(['ruim','neutro','otimo'][i])}
                    style={{background:'transparent',border:'none',fontSize:'2rem',cursor:'pointer',padding:4}}>{e}</button>
                ))}
              </div>
            </div>
          ):(
            <div style={{background:'rgba(51,252,92,.08)',border:'1px solid rgba(51,252,92,.3)',borderRadius:10,padding:'10px',textAlign:'center',marginBottom:12,fontSize:'.78rem',fontWeight:600,color:'#AAFFC2'}}>✓ Obrigado pelo feedback!</div>
          )}
          <button className={styles.btnPrimary} onClick={()=>{setScreen('welcome');setSaved(false);setNpsRated(null);setCNome('');setCEmp('');setCCargo('');setCFone('');setCEmail('');setAnswers({});setAnswerLabels({});setFlow([]);setQIdx(0)}}>
            Novo participante
          </button>
        </div></div>
        {showPin&&<Pin val={pinVal} onVal={handlePin} onCancel={()=>setShowPin(false)}/>}
      </div>
    )
  }

  // ══ ADMIN ══
  if (screen==='admin') {
    const hot=leads.filter(l=>l.temperatura==='quente').length
    const morn=leads.filter(l=>l.temperatura==='morno').length
    const frio=leads.filter(l=>l.temperatura==='frio').length
    const wpp=leads.filter(l=>l.whatsapp).length
    const segs={}; leads.forEach(l=>{if(l.segmento)segs[l.segmento]=(segs[l.segmento]||0)+1})
    const aw={}; leads.forEach(l=>{if(l.conhecia_arclad)aw[l.conhecia_arclad]=(aw[l.conhecia_arclad]||0)+1})
    const awM={ja_cliente:'Já clientes',conhecia:'Conheciam',ouviu_falar:'Ouviram falar',nao_conhecia:'Conheceram na feira'}
    const tCls={quente:styles.tempHot,morno:styles.tempWarm,frio:styles.tempCold}
    const tLbl={quente:'🔥 Quente',morno:'⛅ Morno',frio:'❄️ Frio'}
    return (
      <div className={styles.bg}>
        <Head><title>ARclad · Admin</title></Head>
        <div className={styles.wrap}><div className={styles.card}>
          <div className={styles.topAccent}/>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
            <div>
              <div style={{fontWeight:900,color:'var(--brand-lime)',fontSize:'1.05rem'}}>Painel ARclad</div>
              <div style={{fontSize:'.7rem',fontWeight:500,color:'var(--muted)',marginTop:2}}>{fairName} · Brasil</div>
            </div>
            <button className={styles.btnOut} onClick={()=>setScreen('welcome')} style={{width:'auto',padding:'7px 15px',fontSize:'.75rem',marginTop:0}}>Fechar</button>
          </div>
          <div className={styles.tabRow}>
            {[['leads','👥 Leads'],['report','📊 Relatório']].map(([id,lbl])=>(
              <button key={id} className={`${styles.tab} ${adminTab===id?styles.tabOn:''}`} onClick={()=>setAdminTab(id)}>{lbl}</button>
            ))}
          </div>
          {adminTab==='leads'&&<>
            <div className={styles.statsRow}>
              <div className={styles.statBox}><div className={styles.statV}>{leads.length}</div><div className={styles.statL}>Total</div></div>
              <div className={styles.statBox}><div className={styles.statV} style={{color:'#FFAAAA'}}>{hot}</div><div className={styles.statL}>🔥 Quentes</div></div>
              <div className={styles.statBox}><div className={styles.statV}>{wpp}</div><div className={styles.statL}>WhatsApp</div></div>
            </div>
            <div className={styles.filterRow}>
              {[['todos','Todos'],['quente','🔥 Quente'],['morno','⛅ Morno'],['frio','❄️ Frio']].map(([f,l])=>(
                <button key={f} className={`${styles.fbtn} ${adminFilter===f?styles.fbtnOn:''}`} onClick={()=>setAdminFilter(f)}>{l}</button>
              ))}
            </div>
            <div className={styles.tblWrap}>
              <table className={styles.tbl}>
                <thead><tr><th>Nome / Empresa</th><th>Contato</th><th>Temperatura</th><th>Oportunidade</th></tr></thead>
                <tbody>
                  {fl.length===0
                    ?<tr><td colSpan={4} style={{textAlign:'center',padding:'24px',color:'var(--muted)'}}>Nenhum lead aqui.</td></tr>
                    :fl.slice().reverse().map((l,i)=>(
                      <tr key={i}>
                        <td><strong style={{color:'var(--brand-white)'}}>{l.nome}</strong><br/><small style={{color:'var(--muted)'}}>{l.empresa}</small></td>
                        <td><span style={{color:'var(--brand-lime)',fontWeight:700,fontSize:'.8rem'}}>{l.whatsapp}</span></td>
                        <td><span className={tCls[l.temperatura]||styles.tempWarm}>{tLbl[l.temperatura]||l.temperatura}</span></td>
                        <td style={{fontSize:'.75rem',color:'var(--text-sec)'}}>{l.oportunidade}</td>
                      </tr>
                    ))
                  }
                </tbody>
              </table>
            </div>
            <button className={styles.btnPrimary} onClick={exportExcel}>⬇ Exportar Excel</button>
            <button className={styles.btnOut} onClick={()=>{if(!confirm('Apagar lista local?'))return;setLeads([])}} style={{marginTop:8}}>Limpar lista local</button>
          </>}
          {adminTab==='report'&&(
            <div className={styles.reportBody}>
              <h3>Resumo · {fairName}</h3>
              <p><strong>Total:</strong> {leads.length} leads</p>
              <p><strong>🔥 Quentes:</strong> {hot} · <strong>⛅ Mornos:</strong> {morn} · <strong>❄️ Frios:</strong> {frio}</p>
              <p><strong>Com WhatsApp:</strong> {wpp}</p>
              <hr/>
              {Object.keys(segs).length>0&&<><p><strong>Segmentos:</strong></p><ul>{Object.entries(segs).sort((a,b)=>b[1]-a[1]).map(([k,v])=><li key={k}>{k}: {v}</li>)}</ul></>}
              <p><strong>Brand Awareness ARclad:</strong></p>
              <ul>{Object.entries(aw).map(([k,v])=><li key={k}>{awM[k]||k}: {v}</li>)}</ul>
              {hot>0&&<><hr/><p><strong>🔥 Followup:</strong></p><ul>{leads.filter(l=>l.temperatura==='quente').map((l,i)=><li key={i}><strong>{l.nome}</strong> — {l.empresa} — {l.whatsapp}</li>)}</ul></>}
            </div>
          )}
        </div></div>
        {showPin&&<Pin val={pinVal} onVal={handlePin} onCancel={()=>setShowPin(false)}/>}
      </div>
    )
  }
  return null
}

function Pin({val,onVal,onCancel}){
  return(
    <div style={{position:'fixed',inset:0,background:'rgba(0,30,20,.96)',zIndex:999,display:'flex',alignItems:'center',justifyContent:'center'}}>
      <div style={{background:'var(--card)',border:'1.5px solid rgba(201,255,31,.22)',borderRadius:20,padding:'28px 24px',width:268,textAlign:'center'}}>
        <div style={{fontWeight:900,color:'var(--brand-lime)',marginBottom:5,fontSize:'1rem'}}>🔒 Acesso Restrito</div>
        <div style={{fontSize:'.78rem',color:'var(--muted)',marginBottom:14}}>PIN do painel administrativo</div>
        <input type="password" maxLength={4} value={val} onChange={e=>onVal(e.target.value)} inputMode="numeric" autoFocus placeholder="••••"
          style={{width:'100%',background:'var(--sf)',border:'1.5px solid rgba(201,255,31,.22)',borderRadius:12,padding:12,fontFamily:'Inter',fontSize:'1.4rem',color:'var(--brand-white)',textAlign:'center',letterSpacing:'.35em',marginBottom:12,outline:'none'}}/>
        <button onClick={onCancel} style={{width:'100%',background:'transparent',border:'1.5px solid rgba(201,255,31,.14)',borderRadius:10,padding:12,fontFamily:'Inter',fontWeight:600,color:'var(--muted)',cursor:'pointer',fontSize:'.83rem'}}>Cancelar</button>
      </div>
    </div>
  )
}
